/**
 * Review targets for the crossing rule, generated 2026-08-11 from the
 * validation study (docs/research/2026-08-11-deadspace-study.md, addendum 3).
 *
 * Two classes, both mid-match:
 *   missed_junk  — deleted points the zero-crossing rule did NOT flag
 *                  (the ball track shows at least one net crossing)
 *   flagged_kept — kept points the rule WOULD have flagged
 *                  (no net crossing found in the track)
 *
 * Snapshot data: regenerating requires re-running the study's crossing
 * measurement (assets/crossings2.py) against current tracks and quads.
 * Two matches owned by other accounts were left out; their clips cannot be
 * signed from this page.
 */
export interface CrossingReviewRow {
  readonly pointId: string;
  readonly matchId: string;
  readonly opponent: string;
  readonly venue: string;
  /** Point start in original-video seconds. */
  readonly t0: number;
  /** Point length in seconds. */
  readonly dur: number;
  /** Net crossings measured in the ball track. */
  readonly crossings: number;
  /** Ball detections inside the window (near the table). */
  readonly detections: number;
  readonly cls: "missed_junk" | "flagged_kept";
}

